<template>
<section class="format-workspace" lang="es" spellcheck="true">
 <h3>{{ configurationOnly ? "Configuración documental" : "Carga de formatos" }}</h3><p class="text-center text-muted">{{ configurationOnly ? "Selecciona un documento para configurar sus datos y preparación." : "Carga y actualiza los archivos institucionales de cada sección." }}</p>
 <p v-if="mensaje" class="alert" :class="fallo?'alert-danger':'alert-success'" role="status">{{mensaje}}</p>
 <article v-for="s in secciones" :key="s.id" class="format-section"><button class="section-heading" :aria-expanded="abierta===s.id" :aria-controls="'formato-'+s.id" @click="abierta=abierta===s.id?'':s.id"><i :class="'bi bi-'+s.icono"></i><span><strong>{{s.nombre}}</strong><small>{{s.descripcion}}</small></span><i class="bi bi-chevron-down" :class="{girado:abierta===s.id}"></i></button>
 <div v-if="abierta===s.id" :id="'formato-'+s.id" class="section-content">
 <template v-if="s.id==='listas'">
 <div v-if="manage && !configurationOnly" class="reference-upload"><label>Documento de referencia de listas (Word)<input type="file" accept=".doc,.docx" class="form-control" @change="archivoLista=$event.target.files[0]||null"></label><button class="btn btn-outline-primary mt-2" :disabled="ocupado||!archivoLista" @click="cargarReferenciaLista">Guardar archivo de listas</button><p class="small text-muted mt-2">El archivo se conserva como referencia. El PDF usa la tabla de asistencia del sistema con las fechas configuradas; no reproduce automáticamente el diseño de Word.</p><button v-if="config.formato_listas_documento" class="btn btn-link" @click="descargarReferenciaLista">Descargar referencia guardada</button></div>
 <template v-if="configurationOnly"><button v-if="config.formato_listas_documento" class="btn btn-outline-primary mb-3" @click="descargarReferenciaLista">Descargar referencia vigente</button><p>Las listas se descargan en oficio horizontal desde Procesos escolares → Listas.</p>
 <p class="small">Días comunes: <strong>{{dias.join(' y ') || 'Configúralos primero en Clubes'}}</strong>. Las fechas se calculan por el día real del calendario.</p>
 <form @submit.prevent="guardarCalendario"><label>Periodo escolar<select v-model="calendario.periodo_id" class="form-select" required><option value="">Selecciona periodo</option><option v-for="p in periodos" :key="p.id" :value="p.id">{{p.nombre}}</option></select></label><div class="row g-3 my-2"><label class="col-md-6">Inicio de las actividades<input v-model="calendario.inicio" type="date" class="form-control" required></label><label class="col-md-6">Fin de las actividades<input v-model="calendario.fin" type="date" class="form-control" required></label></div>
 <h5 class="mt-4">Actos cívicos y desfiles</h5><div v-for="(e,i) in calendario.eventos" :key="i" class="event-row"><input v-model="e.fecha" type="date" class="form-control" required aria-label="Fecha especial"><select v-model="e.tipo" class="form-select" aria-label="Tipo de evento"><option>Acto cívico</option><option>Desfile</option></select><input v-model="e.nombre" required maxlength="100" class="form-control" placeholder="Nombre del evento" aria-label="Nombre del evento" spellcheck="true"><button type="button" class="btn btn-outline-danger" @click="calendario.eventos.splice(i,1)" aria-label="Quitar fecha especial"><i class="bi bi-trash"></i></button></div><button type="button" class="btn btn-outline-primary mt-2" @click="calendario.eventos.push({fecha:'',tipo:'Acto cívico',nombre:''})">Agregar fecha especial</button>
 <div v-if="resumenFechas.length" class="calendar-preview"><strong>{{resumenFechas.length}} fechas en total</strong><span v-for="f in resumenFechas" :key="f.fecha" :class="{'special-date':f.tipo!=='Club'}">{{f.fecha.split('-').reverse().join('/')}} · {{f.tipo}} {{f.nombre}}</span></div><p v-else class="text-muted mt-3">Completa el intervalo para ver las fechas.</p><button class="btn btn-primary mt-3" :disabled="ocupado">Guardar calendario de listas</button></form></template>
 </template>
 <FormatosInstitucionales v-else :key="s.codigo" :section-code="s.codigo" :manage="manage" :upload-only="!configurationOnly" :configuration-only="configurationOnly" />
 <form v-if="configurationOnly && s.id==='constancia' && manage" @submit.prevent="guardarConstancia" class="settings-form"><h5>Datos de emisión</h5><div class="row g-3"><label class="col-md-6">Lugar de emisión<input v-model="config.constancia_lugar" class="form-control" maxlength="150" required></label><label class="col-md-6">Fecha de emisión<input v-model="config.constancia_fecha" type="date" class="form-control" required></label><label class="col-md-6">Jefe de oficina de promoción<input v-model="config.firma_jefe_promocion" class="form-control" maxlength="150" required></label><label class="col-md-6">Jefe de actividades extraescolares<input v-model="config.firma_jefe_actividades" class="form-control" maxlength="150" required></label></div><label class="mt-3">Responsable de Servicios Escolares<input v-model="config.firma_jefa_servicios" class="form-control" maxlength="150"></label><label class="mt-3">Texto de la constancia<textarea v-model="config.constancia_texto" class="form-control" rows="5" maxlength="5000"></textarea></label><details class="small text-muted mt-2"><summary>Campos disponibles para el texto</summary><p>{nombre}, {control}, {carrera}, {club}, {desempeno}, {valor}, {periodo}. Deja el texto vacío para usar el texto institucional.</p></details><button class="btn btn-primary mt-3" :disabled="ocupado">Guardar datos de constancias</button></form>
 <form v-if="configurationOnly && s.id==='evaluacion' && manage" class="settings-form" @submit.prevent="guardarEvaluacion"><h5>Preguntas y porcentajes</h5><label>Periodo de aplicación<select v-model="periodoEvaluacion" class="form-select" required @change="cargarEvaluacion"><option value="">Selecciona periodo</option><option v-for="p in periodos" :key="p.id" :value="p.id">{{p.nombre}}</option></select></label><p class="small text-muted mt-2">Solo se pueden cambiar las reglas de periodos sin evaluaciones guardadas. Se conserva la escala de 0 a 4.</p><div v-for="(pregunta,i) in preguntas" :key="i" class="row g-3 mb-3"><label class="col-md-9">Pregunta {{i+1}}<textarea v-model="preguntas[i]" required minlength="5" maxlength="500" class="form-control" rows="2"></textarea></label><label class="col-md-3">Porcentaje<input v-model.number="pesos[i]" type="number" step="any" min="0.01" max="100" class="form-control" required></label></div><p>Total: <strong>{{pesos.reduce((a,b)=>a+Number(b||0),0).toFixed(2)}}%</strong></p><button class="btn btn-primary" :disabled="ocupado">Guardar reglas de evaluación</button></form>
 </div></article>
</section>
</template>
<script>
import api from '../servicios/cliente-http';
import {uploadDocumento} from '../servicios/api';
import {openDocumentFile} from '../servicios/archivos-documentos';
import FormatosInstitucionales from './FormatosInstitucionales.vue';
import {fechasListas} from '../servicios/calendario-listas';
import {evaluationCriteria} from '../servicios/reglas-evaluacion';
export default{components:{FormatosInstitucionales},props:{manage:Boolean,configurationOnly:Boolean},data:()=>({abierta:'listas',archivoLista:null,mensaje:'',fallo:false,ocupado:false,config:{},dias:[],periodos:[],criterios:evaluationCriteria,periodoEvaluacion:'',preguntas:[...evaluationCriteria],pesos:Array(7).fill(100/7),calendario:{periodo_id:'',inicio:'',fin:'',eventos:[]},secciones:[{id:'listas',nombre:'Formato de Listas de clubes',icono:'calendar3',descripcion:'Calendario semanal, actos cívicos y desfiles'},{id:'constancia',codigo:'003-05',nombre:'Formato de Constancias',icono:'award',descripcion:'Documento vigente y datos de emisión'},{id:'registro',codigo:'003-01',nombre:'Formato de Registro de Participantes',icono:'people',descripcion:'Archivo institucional de inscripción'},{id:'evaluacion',codigo:'003-04',nombre:'Formato de Evaluación de Monitores',icono:'clipboard-check',descripcion:'Archivo y criterios de evaluación'},{id:'resultados',codigo:'003-03',nombre:'Formato de Resultados y Firmas',icono:'pen',descripcion:'Resultados por club y espacios para firmas'}]}),computed:{resumenFechas(){try{return fechasListas(this.calendario,this.dias);}catch{return [];}}},async mounted(){try{const [c,p]=await Promise.all([api.get('/config'),api.get('/periodos')]);this.config=Object.fromEntries(c.data.data.map(r=>[r.clave,r.valor]));this.periodos=p.data.data;this.dias=JSON.parse(this.config.clubs_horario_semanal || '{"dias":[]}').dias;this.config.constancia_fecha ||= new Date().toLocaleDateString('en-CA');if(this.config.listas_calendario)this.calendario=JSON.parse(this.config.listas_calendario);}catch(e){this.notificar(e.message,true);}},methods:{async cargarReferenciaLista(){if(!this.manage||!this.archivoLista||this.ocupado)return;if(this.archivoLista.size>5*1024*1024||!(/\.docx?$/i.test(this.archivoLista.name))){this.notificar('Selecciona un Word de hasta 5 MB.',true);return;}this.ocupado=true;try{const f=new FormData();f.append('archivo',this.archivoLista);f.append('tipo','OTRO');f.append('concepto','Referencia de listas de clubes');const r=await uploadDocumento(f);await api.post('/config',{clave:'formato_listas_documento',valor:String(r.data.id)});this.config.formato_listas_documento=String(r.data.id);this.notificar('Referencia de listas guardada.');}catch(e){this.notificar(e.message,true);}finally{this.ocupado=false;}},async descargarReferenciaLista(){try{const r=await api.get('/documentos/'+this.config.formato_listas_documento,{responseType:'blob'});openDocumentFile(r.data,'Formato_listas');}catch(e){this.notificar(e.message,true);}},async cargarEvaluacion(){try{const {data}=await api.get("/config",{params:{clave:"evaluacion_config_"+this.periodoEvaluacion}});const c=data.data?.valor?JSON.parse(data.data.valor):null;this.preguntas=c?.preguntas || [...evaluationCriteria];this.pesos=c?.pesos || Array(7).fill(100/7);}catch(e){this.notificar(e.message,true);}},async guardarEvaluacion(){if(!this.manage||this.ocupado)return;this.ocupado=true;try{await api.post("/config",{clave:"evaluacion_config_"+this.periodoEvaluacion,valor:JSON.stringify({preguntas:this.preguntas,pesos:this.pesos})});this.notificar("Preguntas y porcentajes guardados para el periodo seleccionado.");}catch(e){this.notificar(e.response?.data?.statusMessage||e.message,true);}finally{this.ocupado=false;}},notificar(m,f=false){this.mensaje=m;this.fallo=f;},async guardarCalendario(){if(!this.manage||this.ocupado)return;try{const fechas=fechasListas(this.calendario,this.dias);const p=this.periodos.find(p=>Number(p.id)===Number(this.calendario.periodo_id));if(!p||this.calendario.inicio<String(p.fecha_inicio).slice(0,10)||this.calendario.fin>String(p.fecha_fin).slice(0,10))throw Error('El intervalo debe estar dentro del periodo seleccionado.');this.ocupado=true;await api.post('/config',{clave:'listas_calendario',valor:JSON.stringify({...this.calendario,dias:this.dias,fechas})});this.notificar('Calendario guardado. Se aplicará al PDF de las listas de este periodo.');}catch(e){this.notificar(e.response?.data?.statusMessage||e.message,true);}finally{this.ocupado=false;}},async guardarConstancia(){if(!this.manage||this.ocupado)return;this.ocupado=true;try{for(const clave of ['constancia_lugar','constancia_fecha','firma_jefe_promocion','firma_jefe_actividades','firma_jefa_servicios','constancia_texto'])await api.post('/config',{clave,valor:this.config[clave]||''});this.notificar('Datos de emisión guardados.');}catch(e){this.notificar(e.message,true);}finally{this.ocupado=false;}}}};
</script>
<style scoped>.format-workspace{max-width:1100px;margin:auto}.format-section{background:#ffffffd9;border:1px solid #dae6fa;border-radius:22px;margin:16px 0;overflow:hidden;box-shadow:0 8px 28px #26477a0a}.section-heading{display:flex;align-items:center;gap:16px;width:100%;border:0;padding:22px;text-align:left;background:linear-gradient(120deg,#edf4ff,#fff);color:#274875}.section-heading>i:first-child{background:#dfeaff;color:#346bc8;padding:12px;border-radius:14px;font-size:1.25rem}.section-heading span{flex:1}.section-heading strong,.section-heading small{display:block}.section-heading strong{font-family:Manrope,sans-serif;font-size:1rem}.section-heading small{margin-top:6px;color:#68809f}.section-heading>i:last-child{transition:transform .25s}.girado{transform:rotate(180deg)}.section-content{padding:24px;animation:reveal .25s ease}.settings-form{border-top:1px solid #dfE8f7;margin-top:22px;padding-top:22px}label{display:block;font-size:.85rem;font-weight:600}.form-control,.form-select{margin-top:6px;border-radius:12px;border-color:#cfdff6;padding:11px}.event-row{display:grid;grid-template-columns:1fr 1fr 2fr auto;gap:8px;margin-bottom:10px}.calendar-preview{display:flex;flex-wrap:wrap;gap:8px;max-height:260px;overflow:auto;margin-top:20px;padding:14px;background:#f4f8ff;border-radius:14px}.calendar-preview strong{width:100%}.calendar-preview span{padding:5px 8px;background:white;border:1px solid #dce6fa;border-radius:8px;font-size:.75rem}.calendar-preview .special-date{background:#fff2d1;border-color:#f0ce74}.btn{border-radius:12px;transition:transform .2s}.btn:hover{transform:translateY(-2px)}@keyframes reveal{from{opacity:0;transform:translateY(6px)}to{opacity:1;transform:none}}@media(max-width:650px){.event-row{grid-template-columns:1fr}.section-content{padding:16px}}@media(prefers-reduced-motion:reduce){.section-content{animation:none}.btn,.section-heading>i{transition:none}}</style>
